# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [parse_span("09:07-17:08")]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [parse_span("09:05-10:24")]
        self.assertEqual(
            round_spans(spans, 10),
            ["09:10-10:20 (1h 10m)"]
        )

    def test_one_label_per_span(self):
        spans = [
            parse_span("08:00-09:00"),
            parse_span("10:00-10:30")
        ]
        self.assertEqual(
            round_spans(spans, 30),
            ["08:00-09:00 (1h 0m)", "10:00-10:30 (0h 30m)"]
        )

    def test_bad_steps_raise(self):
        spans = [parse_span("09:00-10:00")]
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                round_spans(spans, step)


if __name__ == "__main__":
    unittest.main()
